from itertools import combinations
# R(A,B,C,D) with FDs: AB -> C, C -> D, D -> A
attrs = "ABCD"
fds = [("AB", "C"), ("C", "D"), ("D", "A")]
print("attributes:", attrs, "FDs:", fds)

def closure(x):
    # Keep adding right sides whose left side is already inside the set
    result = set(x)
    changed = True
    while changed:
        changed = False
        for left, right in fds:
            if set(left) <= result and not set(right) <= result:
                result |= set(right)
                changed = True
    return "".join(sorted(result))

print("closure of AB:", closure("AB"))
print("closure of C:", closure("C"))
keys = []
for size in range(1, len(attrs) + 1):
    for combo in combinations(attrs, size):
        x = "".join(combo)
        # Skip supersets of keys already found: they are superkeys, not candidate keys
        if any(set(k) <= set(x) for k in keys):
            continue
        if closure(x) == attrs:
            keys.append(x)
print("candidate keys:", keys)
print("prime attributes:", sorted(set("".join(keys))))
# Cost: 2^n subsets in the worst case, each closure is polynomial
